    # ---------- 3.9.0 · n° 111 titre écrit tout seul, n° 108 case « Match à domicile » ----------
    val = lambda: pg.input_value('#et')
    act('[data-act=evnew]')
    check('n° 111 : nouveau rendez-vous : titre écrit tout seul (« Entraînement - … »)', val().startswith('Entraînement - ') and has('Écrit tout seul'))
    act('[data-act=evaud][data-v=team]'); act('[data-act=evteam][data-id=t-u9]')
    check('n° 111 : entraînement : catégorie et genre de l’équipe, jamais son nom', val().startswith('Entraînement U9 mixte - '))
    pg.check('[data-evrep]'); pg.wait_for_timeout(250)
    check('n° 111 : entraînement répété : « chaque <jour> <heure> »', ' - chaque ' in val())
    act('[data-act=evtype][data-v=Match]')
    check('n° 108 : case « Match à domicile » visible dès qu’on choisit un match', pg.locator('.homebox [data-evhome]').count() == 1 and has('Match à domicile'))
    check('n° 111 : adversaire et date avant le titre', pg.evaluate("(() => { const f = [...document.querySelectorAll('#evf input')].map(i => i.id); return f.indexOf('eo') < f.indexOf('et') && f.indexOf('ed') < f.indexOf('et'); })()"))
    pg.evaluate("(() => { const i = document.querySelector('#evf [name=starts_at]'); i.value = '2026-11-10T14:00'; i.dispatchEvent(new Event('change', { bubbles: true })); })()"); pg.wait_for_timeout(250)
    pg.fill('#eo', 'Palaiseau'); pg.wait_for_timeout(150)
    check('n° 111 : « Match vs Palaiseau - 10/11/26 » rempli tout seul', val() == 'Match vs Palaiseau - 10/11/26')
