    check('restauration de la fiche', pg.evaluate("!window.__FAKE.players.find(p => p.id === 'p-tom').deleted_at"))
    act('[data-act=tab][data-i="0"]'); act('[data-act=espace]'); act('[data-act=casq][data-v=coach]')
    check('n° 95 · espace coach : « Ajouter des joueurs » pour son équipe', pg.locator('[data-act=import][data-id=t-u9]').count() == 1)
